package org.eclipse.ui.internal.editors.text.codemining.annotation;

import org.eclipse.jface.text.IDocument;
import org.eclipse.jface.text.codemining.AbstractCodeMining;
import org.eclipse.jface.text.codemining.ICodeMiningProvider;
import org.eclipse.jface.text.source.Annotation;
import org.eclipse.swt.graphics.Point;
import org.eclipse.swt.graphics.GC;
import org.eclipse.swt.graphics.Color;
import org.eclipse.swt.widgets.StyledText;

public class AnnotationCodeMining extends AbstractCodeMining {
    private Annotation annotation;
    private Object annotationAccess; // Placeholder to make it compile

    public AnnotationCodeMining(int lineNumber, IDocument document, ICodeMiningProvider provider, Annotation annotation, Runnable action, Object annotationAccess) {
        super(lineNumber, document, provider, action);
        this.annotationAccess = annotationAccess;
        setLabel(org.eclipse.ui.internal.editors.text.codemining.annotation.AnnotationCodeMining.sanitizeLabel(annotation.getText())); // Transformed
        this.annotation = annotation;
    }

    private static String sanitizeLabel(String label) {
        return label.replace('\r', ' ').replace('\n', ' ');
    }

    @Override
    public Point draw(GC gc, StyledText textWidget, Color color, int x, int y) { return null; }
}

